/* @autogenerated */
import { NgTemplateOutlet } from '@angular/common';
import { Component, contentChild, Directive, inject, input, Input, viewChild } from '@angular/core';
import {
  MAT_FORM_FIELD,
  MatFormField,
  MatFormFieldControl,
  MatFormFieldModule,
  MatSuffix,
} from '@angular/material/form-field';
import { TranslocoModule } from '@jsverse/transloco';
import { BaseEditable } from '../base-editable';
import { EditableHiddenMarkComponent } from '../editable-hidden-mark/editable-hidden-mark.component';

/**
 * mat-form-field solo detecta el control entre su propio contenido: el que proyecta el editable
 * se le asigna aquí, antes de su ngAfterContentInit.
 */
@Directive({ selector: 'mat-form-field[editableFieldControl]' })
export class EditableFieldControlDirective {
  private readonly formField = inject(MatFormField);

  @Input({ required: true }) set editableFieldControl(control: MatFormFieldControl<unknown> | undefined) {
    if (control) {
      this.formField._control = control;
    }
  }
}

/**
 * El control proyectado pide su mat-form-field (MAT_FORM_FIELD) al crearse, antes que la vista del envoltorio:
 * se le da un intermediario que delega en el mat-form-field del envoltorio.
 */
function projectedFormField(): MatFormField {
  const field = inject(EditableFieldComponent);
  return new Proxy({} as MatFormField, {
    // Antes de crear la vista solo se consulta al instanciar (Angular en modo desarrollo, `!!formField`)
    get: (_, prop) => {
      const target = field.formField() as any;
      const value = target?.[prop];
      return typeof value === 'function' ? value.bind(target) : value;
    },
    set: (_, prop, value) => {
      const target = field.formField() as any;
      if (target) {
        target[prop] = value;
      }
      return true;
    },
  });
}

/**
 * Estructura común de los editables con mat-form-field: label, ayuda, errores, visibilidad y marca de oculto.
 * El editable proyecta su control y sus `matSuffix`.
 *
 * El mat-form-field no va dentro de ningún @if: tiene que existir antes de que el control proyectado lo consulte
 * (mat-select lo hace en su primer ngDoCheck). Si el campo no es visible se oculta y se le quita el control.
 */
@Component({
  selector: 'editable-field',
  imports: [
    NgTemplateOutlet,
    MatFormFieldModule,
    TranslocoModule,
    EditableHiddenMarkComponent,
    EditableFieldControlDirective,
  ],
  providers: [{ provide: MAT_FORM_FIELD, useFactory: projectedFormField }],
  template: `
    <ng-template #content><ng-content /></ng-template>
    <ng-template #suffixContent><ng-content select="[matSuffix], [matIconSuffix], [matTextSuffix]" /></ng-template>
    @let field = editable();
    <mat-form-field
      [class.editable-field-off]="!field.visible()"
      [appearance]="field.appearance()!"
      [editableFieldControl]="control()"
    >
      <mat-label>{{ field.label() + '.label' | transloco }}</mat-label>
      <!-- Un bloque por elemento: mat-form-field solo reparte en sus slots los bloques con una única raíz -->
      @if (field.visible()) {
        <ng-container *ngTemplateOutlet="content" />
      }
      @if (field.visible() && suffix()) {
        <span matSuffix class="editable-field-suffix"><ng-container *ngTemplateOutlet="suffixContent" /></span>
      }
      @if (field.visible() && field.hintKey(); as hint) {
        <mat-hint>{{ hint | transloco }}</mat-hint>
      }
      @for (error of field.visible() ? field.errorList() : []; track error.key) {
        <mat-error>{{ field.errorKey(error) | transloco: error.params }}</mat-error>
      }
    </mat-form-field>
    @if (!field.visible() && field.showHiddenMark()) {
      <editable-hidden-mark [label]="field.label()" />
    }
  `,
  styles: [
    `
      :host {
        display: contents;
      }
      .editable-field-off {
        display: none;
      }
      .editable-field-suffix {
        display: flex;
        align-items: center;
      }
    `,
  ],
})
export class EditableFieldComponent {
  editable = input.required<BaseEditable<any>>();

  readonly formField = viewChild(MatFormField);
  protected readonly control = contentChild(MatFormFieldControl, { descendants: true });
  protected readonly suffix = contentChild(MatSuffix, { descendants: true });
}

/**
 * Variante sin mat-form-field, para controles que no lo admiten (check, grupos de campos, listas):
 * proyecta el control y pinta debajo la ayuda y los errores.
 */
@Component({
  selector: 'editable-bare-field',
  imports: [MatFormFieldModule, TranslocoModule, EditableHiddenMarkComponent],
  template: `
    @let field = editable();
    @if (field.visible()) {
      <ng-content />
      <div class="editable-field-subscript">
        @if (field.hintKey(); as hint) {
          <mat-hint>{{ hint | transloco }}</mat-hint>
        }
        @for (error of field.errorList(); track error.key) {
          <mat-error>{{ field.errorKey(error) | transloco: error.params }}</mat-error>
        }
      </div>
    } @else if (field.showHiddenMark()) {
      <editable-hidden-mark [label]="field.label()" />
    }
  `,
  styles: [
    `
      :host {
        display: contents;
      }
      .editable-field-subscript {
        /* En editables con los campos en fila, los mensajes pasan a su propia línea */
        flex-basis: 100%;
        padding: 0 16px;
        font: var(--mat-sys-body-small);
      }
      .editable-field-subscript:empty {
        display: none;
      }
    `,
  ],
})
export class EditableBareFieldComponent {
  editable = input.required<BaseEditable<any>>();
}
